from nu import *
mb=['Options','Shop',"What's New",'Edit Mode','Support','Macros','AddOns','Ratings']
gm=bwin(X,Y,215,470,'Game Menu','<div style="padding:10px;display:flex;flex-direction:column;gap:6px">'+px('<span class="btn pri" style="width:175px">◆ Phoenix UI</span>',False)+''.join(f'<span class="btn" style="width:175px">{m}</span>' for m in mb)+'<div style="height:6px"></div>'+''.join(f'<span class="btn" style="width:175px">{m}</span>' for m in ['Log Out','Exit Game'])+'<span class="btn pri" style="width:175px">Return to Game</span></div>',portrait=False,cog=False)
def pop(t,b,w=320,danger=False): return f'<div class="card" style="background:var(--bg1);width:{w}px;padding:12px;text-align:center;box-shadow:0 10px 26px #000;border-color:{"#d33" if danger else "var(--acc)"}">{b}</div>'
p1=pop('','<div style="font-size:20px" class="bad">⚠</div><div>Delete <b style="color:#a335ee">Band of Embers</b>?<br>Type DELETE to confirm.</div><div style="margin:8px auto;width:200px">'+inp('DELETE',200)+'</div>'+px('<span class="btn" style="background:#8a2020;border-color:#d33">Delete</span>')+btn('Cancel'),danger=True)
p2=pop('','<div>Set price for selected item:</div><div style="margin:6px auto;width:200px">'+inp('100 g 0 s 0 c',200)+'</div><div style="display:flex;gap:8px;justify-content:center;align-items:center">'+ic('diamond_hard','#5a3a90',36,q='rare')+'Radiant Gem</div><div style="margin-top:6px">'+btn('Accept','pri')+btn('Option')+btn('Other')+btn('Cancel')+'</div>')
p3=pop('','<div style="display:flex;gap:10px;align-items:center">'+ic('crown','#a05010',44)+'<div style="text-align:left">Thrall has initiated a ready check.<br><span class="mut">Are you ready?</span></div></div><div style="margin-top:8px">'+btn('Yes','pri')+btn('No')+'</div>')
p4=pop('','<div>Confirm your role</div><div style="display:flex;gap:10px;justify-content:center;margin:8px">'+''.join(f'<span class="btn {"pri" if i==2 else ""}" style="width:48px;height:48px;font-size:20px">{s}</span>' for i,s in enumerate(['🛡','✚','⚔']))+'</div>'+btn('Accept','pri')+btn('Cancel'))
p5=pop('','<b>Your group is ready!</b><div class="mut">Ashen Spire — Heroic</div><div style="display:flex;justify-content:center;gap:4px;margin:6px">'+''.join(f'<span style="width:20px;height:20px;border-radius:50%;background:{"var(--ok)" if i<3 else "var(--bg3)"}"></span>' for i in range(5))+'</div>'+btn('Enter Dungeon','pri')+btn('Leave Queue'))
body=gm+at(X+240,Y,'<div style="display:grid;grid-template-columns:320px 320px;gap:14px">'+p1+p2+p3+p4+p5+'</div>',z=12)
fl=fly(X+240,Y+520,'Popups',[('Danger colour for destructive','<span class="tg on"></span>'),('Phoenix entry in menu','<span class="tg on"></span>')])
page2('20_game_menu_popups','Blizzard GameMenuFrame + StaticPopup / ReadyCheck / RoleCheck / LFG proposal · Ember',body+fl)
